//! Embedded world land mask (Natural Earth 1:110m, public domain).
//!
//! The bitmap is 720x360, equirectangular, 1 bit per pixel, row-major MSB
//! first.  It is generated by `tools/gen_land.py`.

pub const MASK_W: usize = 720;
pub const MASK_H: usize = 360;
pub const MASK_BYTES: usize = MASK_W * MASK_H / 8;

static LAND: &[u8; MASK_BYTES] = include_bytes!("data/land_720x360.bin");

#[inline]
fn bit_at(x: usize, y: usize) -> bool {
    let i = y * MASK_W + x;
    LAND[i >> 3] & (1 << (7 - (i & 7))) != 0
}

#[inline]
pub fn lon_to_x(lon: f32) -> f32 {
    (lon.clamp(-180.0, 180.0) + 180.0) * (MASK_W as f32 / 360.0)
}

#[inline]
pub fn lat_to_y(lat: f32) -> f32 {
    (90.0 - lat.clamp(-90.0, 90.0)) * (MASK_H as f32 / 180.0)
}

/// Is a single lon/lat point on land?
pub fn is_land(lon: f32, lat: f32) -> bool {
    let x = lon_to_x(lon) as usize;
    let y = lat_to_y(lat) as usize;
    bit_at(x.min(MASK_W - 1), y.min(MASK_H - 1))
}

/// Fraction of land in a lon/lat box (sampled on a regular grid).
pub fn coverage(lon0: f32, lon1: f32, lat0: f32, lat1: f32, samples: usize) -> f32 {
    let n = samples.max(1);
    let mut hit = 0usize;
    for j in 0..n {
        let v = (j as f32 + 0.5) / n as f32;
        let lat = lat0 + (lat1 - lat0) * v;
        for i in 0..n {
            let u = (i as f32 + 0.5) / n as f32;
            let lon = lon0 + (lon1 - lon0) * u;
            if is_land(lon, lat) {
                hit += 1;
            }
        }
    }
    hit as f32 / (n * n) as f32
}

/// Coverage of the map-cell rectangle at integer grid position (x, y).
pub fn cell_coverage(x: usize, y: usize, w: usize, h: usize, samples: usize) -> f32 {
    let lon0 = -180.0 + (x as f32 / w as f32) * 360.0;
    let lon1 = -180.0 + ((x + 1) as f32 / w as f32) * 360.0;
    let lat0 = 90.0 - (y as f32 / h as f32) * 180.0;
    let lat1 = 90.0 - ((y + 1) as f32 / h as f32) * 180.0;
    coverage(lon0, lon1, lat0, lat1, samples)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn mask_has_expected_geography() {
        assert!(is_land(-40.0, 72.0), "Greenland");
        assert!(is_land(20.0, 20.0), "Sahara");
        assert!(is_land(135.0, -25.0), "Australia");
        assert!(is_land(78.0, 22.0), "India");
        assert!(!is_land(-150.0, 0.0), "Pacific");
        assert!(!is_land(-30.0, 55.0), "North Atlantic");
        assert!(!is_land(0.0, 89.0), "Arctic Ocean");
        assert!(is_land(0.0, -85.0), "Antarctica");
    }

    #[test]
    fn coverage_extremes() {
        assert_eq!(coverage(10.0, 11.0, 20.0, 21.0, 3), 1.0);
        assert_eq!(coverage(-150.0, -149.0, 0.0, 1.0, 3), 0.0);
    }
}
